svg.script:
{
  "projectName": "Food Delivery System - Phase 1",
  "projectCode": "FDS-2024-01",
  "version": "1.0",
  "lastUpdated": "2024-01-15",
  "businessCase": {
    "businessNeed": "Develop a scalable, cloud-native food delivery platform to capture emerging market demand and improve customer experience",
    "expectedBenefits": "15% revenue increase, 25% improvement in delivery time, enhanced customer retention",
    "strategicAlignment": "Align with digital transformation initiative and customer-first strategy"
  },
  "projectObjectives": [
    { "id": "obj1", "objective": "Deliver MVP with core features (order placement, real-time tracking, payment)", "kpis": ["MVP deployment in Q1", "90% uptime", "< 100ms API response"] },
    { "id": "obj2", "objective": "Achieve seamless restaurant and driver onboarding", "kpis": ["500 restaurants onboarded", "1000 drivers registered", "< 48hr approval time"] },
    { "id": "obj3", "objective": "Implement real-time order tracking and notifications", "kpis": ["99% tracking accuracy", "< 2s notification delay"] }
  ],
  "projectScope": {
    "inScope": ["Mobile app (iOS/Android)", "Restaurant dashboard", "Driver app", "Payment gateway integration", "Real-time tracking", "Customer support chat"],
    "outOfScope": ["Marketing campaigns", "Logistics network setup", "Third-party restaurant integrations (Phase 2)"]
  },
  "stakeholders": [
    { "id": "pm", "name": "John Smith", "role": "Project Manager", "department": "Product", "engagement": "High" },
    { "id": "sponsor", "name": "Sarah Chen", "role": "Executive Sponsor", "department": "C-Suite", "engagement": "Strategic" },
    { "id": "tech", "name": "Mike Johnson", "role": "Tech Lead", "department": "Engineering", "engagement": "High" },
    { "id": "qa", "name": "Emma Davis", "role": "QA Lead", "department": "Quality", "engagement": "Medium" }
  ],
  "timeline": {
    "projectStart": "2024-01-15",
    "projectEnd": "2024-06-30",
    "phases": [
      { "phase": "Planning & Design", "start": "2024-01-15", "end": "2024-02-28", "duration": "6 weeks" },
      { "phase": "Development", "start": "2024-03-01", "end": "2024-05-15", "duration": "11 weeks" },
      { "phase": "Testing & Deployment", "start": "2024-05-16", "end": "2024-06-30", "duration": "6 weeks" }
    ]
  },
  "budget": {
    "total": "$2,500,000",
    "breakdown": [
      { "category": "Engineering", "percentage": 45, "amount": "$1,125,000" },
      { "category": "Infrastructure", "percentage": 25, "amount": "$625,000" },
      { "category": "Testing & QA", "percentage": 15, "amount": "$375,000" },
      { "category": "Contingency", "percentage": 15, "amount": "$375,000" }
    ]
  },
  "constraints": [
    { "type": "Technical", "description": "Must integrate with 3+ payment gateways", "impact": "High" },
    { "type": "Regulatory", "description": "Compliance with food safety and data privacy regulations", "impact": "Critical" },
    { "type": "Timeline", "description": "Must launch MVP before Q2 holiday season", "impact": "High" }
  ],
  "assumptions": [
    "All stakeholders will be available for weekly sync meetings",
    "Third-party APIs (payment, mapping) will have > 99% uptime",
    "Team capacity remains stable throughout project duration",
    "No major scope changes after charter approval"
  ],
  "designTokens": {
    "lightMode": {
      "canvas": "#FFFFFF",
      "fill": "#E5E5E5",
      "stroke": "#1A1A1A",
      "text": "#1A1A1A",
      "muted": "#8A8A85"
    },
    "darkMode": {
      "canvas": "#0D0D0D",
      "fill": "#1E1E1E",
      "stroke": "#F2F2F2",
      "text": "#F2F2F2",
      "muted": "#8A8A85"
    }
  }
}

